import{_ as t,o as l,c as i,a2 as e}from"./chunks/framework.mzJ8I8R4.js";const c=JSON.parse('{"title":"基本用法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basics.md","filePath":"guide/basics.md"}'),r={name:"guide/basics.md"};function d(o,a,h,n,p,s){return l(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h1><h2 id="几个概念" tabindex="-1">几个概念 <a class="header-anchor" href="#几个概念" aria-label="Permalink to &quot;几个概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>叫法</th><th>意思</th></tr></thead><tbody><tr><td>事项</td><td>一件要做的事。有标题，可以写描述、设截止时间</td></tr><tr><td>前置、后续</td><td>“A 完成后才能做 B”：A 是 B 的前置，B 是 A 的后续</td></tr><tr><td>可做</td><td>前置都已完成（或没有前置），现在就能做</td></tr><tr><td>等待中</td><td>还有前置没完成，显示为灰色，标着“等 N 项”</td></tr><tr><td>接下来</td><td>首页，列出所有可做的事项</td></tr><tr><td>文件夹</td><td>用来分开不同的项目，可以一层层嵌套</td></tr></tbody></table><p>一件事拆成几步、步骤之间有先后时，把每一步写成一个事项，再用前置连起来。“接下来”里就只出现当前该做的那一步。</p><h2 id="添加事项" tabindex="-1">添加事项 <a class="header-anchor" href="#添加事项" aria-label="Permalink to &quot;添加事项&quot;">​</a></h2><p>在添加框里写下标题，按回车。添加框在手机屏幕底部，电脑上在标题下方。</p><ul><li>在文件夹里添加的，放进这个文件夹。</li><li>在“接下来”里添加的，放进添加框右侧选中的文件夹，默认是最外层（根目录）。</li><li>没提交的文字会留在框里，切换页面或关掉 App 也不会丢。</li></ul><p>想一次写一大段、让 AI 拆成几项，见 <a href="./ai">AI 整理</a>。</p><h2 id="编辑事项" tabindex="-1">编辑事项 <a class="header-anchor" href="#编辑事项" aria-label="Permalink to &quot;编辑事项&quot;">​</a></h2><p>点一个事项打开详情：手机上从底部弹出，往上拉可以展开；电脑上在右侧。在详情里可以：</p><ul><li>改标题。</li><li>写描述。描述支持 Markdown，以 <code>- [ ] </code> 开头的行是清单项，可以直接点选。</li><li>点“文件夹”换到别的文件夹。</li><li>设截止时间和提醒，见<a href="#截止和提醒">截止和提醒</a>。</li><li>添加或移除前置和后续，见下一节。</li><li>点最下方的“删除事项”删除它。</li></ul><h2 id="设置先后" tabindex="-1">设置先后 <a class="header-anchor" href="#设置先后" aria-label="Permalink to &quot;设置先后&quot;">​</a></h2><p>在详情里：</p><ul><li>“前置”一节列出“以下事项完成后，才能开始此项”。点“添加前置”，选出要先完成的事项。</li><li>“后续”一节列出“此项完成后，才能开始以下事项”。点“添加后续”添加。</li><li>点某一项右侧的 × 移除这条先后关系。</li></ul><p>选事项时先列出同一个文件夹里的，也可以进入别的文件夹，或在顶部搜索。先后关系可以跨文件夹。会形成循环的（A 等 B、B 又等 A）不能选。</p><p>也可以在<a href="#关系图">关系图</a>里连线。</p><h2 id="完成事项" tabindex="-1">完成事项 <a class="header-anchor" href="#完成事项" aria-label="Permalink to &quot;完成事项&quot;">​</a></h2><p>点事项左侧的圆圈就完成了。完成后：</p><ul><li>它在原处停一会儿再收起。</li><li>因它而解锁的事项出现在“接下来”，提示条写着“解锁了……”。</li><li>提示条上的“撤销”可以撤回这次完成。</li></ul><p>手机上也可以在列表里把一行向右滑到底完成，向左滑到底删除。</p><p>前置还没完成的事项也能直接标为完成（现实里常有跳过的步骤），会先确认一次。</p><p>完成的事项收在“已完成”里：手机上在“接下来”右上角，电脑上在左栏。点圆圈可以恢复成待办。</p><h2 id="文件夹" tabindex="-1">文件夹 <a class="header-anchor" href="#文件夹" aria-label="Permalink to &quot;文件夹&quot;">​</a></h2><ul><li><strong>新建</strong>：点文件夹页顶部的“…”按钮，选“新建子文件夹”；在最外层（根目录）是“新建文件夹”。电脑上也可以在左栏的文件夹上点右键。</li><li><strong>重命名、移动、删除</strong>：同一个菜单里。删除文件夹会连同里面的事项一起删除，删除前会确认，删除后可以撤销。</li><li><strong>排序</strong>：手机上长按一行拿起来拖动，电脑上用鼠标按住直接拖。事项只能在先后关系允许的范围里移动，越界会弹回，并说明是哪一项挡住了。</li></ul><p>文件夹里的事项按先后排列，左侧的“轨道”画出它们之间的先后关系：圆圈是轨道上的节点，线从前置连到后续。</p><h2 id="关系图" tabindex="-1">关系图 <a class="header-anchor" href="#关系图" aria-label="Permalink to &quot;关系图&quot;">​</a></h2><p>在文件夹页顶部把“列表”切换成“关系图”，就能以图的形式看这个文件夹里的先后关系。</p><ul><li>拖动画面平移；手机上双指缩放，电脑上用触控板或鼠标滚轮缩放。</li><li>点一个事项打开它的详情，并高亮它前后的整条链；再点一次关上。</li><li>点“连线”，再依次点前置和后续，就连上了一条先后关系。点一条线可以删除它。</li><li>“显示已完成”“包含子文件夹”两个开关控制显示哪些事项。</li></ul><h2 id="截止和提醒" tabindex="-1">截止和提醒 <a class="header-anchor" href="#截止和提醒" aria-label="Permalink to &quot;截止和提醒&quot;">​</a></h2><p>在详情里点“截止”：</p><ul><li>选一个日期，需要时再加具体时间。</li><li>设了具体时间后，可以选“提醒”：截止时，或提前若干分钟、小时、天。</li></ul><p>Android 和电脑上的 App 会按时弹出提醒（电脑上的 App 要在运行，关掉窗口也算在运行）。过了截止时间还没完成的事项标为红色。</p><p>“接下来”按截止时间分组，有截止时间的排在前面。</p><h2 id="重复的事项" tabindex="-1">重复的事项 <a class="header-anchor" href="#重复的事项" aria-label="Permalink to &quot;重复的事项&quot;">​</a></h2><p>每周开例会、每月交房租这类定期要做的事，设一次就够了。在详情里点“截止”，选好日期，再在“重复”里选每天、每周、每月，或者“自定义”（比如每 2 周、每 30 天）。</p><p>重复的事项点圆圈后不会完成，而是把截止时间顺延到下一次，提示条写着“下一次：……”，点“撤销”可以撤回。下一次从哪天算有两种：</p><ul><li><strong>截止日期算</strong>（默认）：按原来的日程。每周一的例会周三才勾掉，下一次还是下周一。</li><li><strong>完成那天算</strong>：从勾掉那天往后数。每 30 天换一次滤芯，晚了 5 天才换，下一次就是 30 天以后。</li></ul><p>每月 31 号这类日子，遇到短的月份取当月最后一天。不想再重复时，把“重复”改回“不重复”，再点圆圈就真正完成了。</p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><ul><li>电脑上：左栏的“搜索”。</li><li>手机上：“文件夹”页顶部的搜索框。</li></ul><p>按标题和描述搜索所有文件夹里的事项，结果标着所在的文件夹。</p><h2 id="撤销" tabindex="-1">撤销 <a class="header-anchor" href="#撤销" aria-label="Permalink to &quot;撤销&quot;">​</a></h2><p>完成、删除、移动这类操作后，屏幕下方的提示条上有“撤销”，几秒内点它就能撤回。agent 做的改动也会这样提示。</p>',43)])])}const b=t(r,[["render",d]]);export{c as __pageData,b as default};
